`timescale 1ns/1ps

// ============================================================================
// axis_data_fifo_0.v — SIMULATION SURROGATE FOR XILINX IP
//
// This module perfectly mimics the ports of the "AXI4-Stream FIFO" IP
// generated by Vivado (Independent Clocks, 256 depth). 
// 
// When you run iverilog, it simulates the Async FIFO behavior.
// When you run Vivado Synthesis, you MUST delete this file and use the 
// real IP block you generated from the IP Catalog!
// ============================================================================

module axis_data_fifo_0 (
    input  wire       s_axis_aresetn,
    input  wire       s_axis_aclk,
    input  wire [7:0] s_axis_tdata,
    input  wire       s_axis_tvalid,
    output wire       s_axis_tready,
    input  wire       s_axis_tlast,
    
    input  wire       m_axis_aclk,
    output wire [7:0] m_axis_tdata,
    output wire       m_axis_tvalid,
    input  wire       m_axis_tready,
    output wire       m_axis_tlast
);

    // 256-deep memory holding 8-bit data + 1-bit tlast
    reg [8:0] mem [0:255];
    reg [7:0] wptr = 0;
    reg [7:0] rptr = 0;

    // ── Write Domain ──
    always @(posedge s_axis_aclk or negedge s_axis_aresetn) begin
        if (!s_axis_aresetn) wptr <= 0;
        else if (s_axis_tvalid && s_axis_tready) begin
            mem[wptr] <= {s_axis_tlast, s_axis_tdata};
            wptr <= wptr + 1;
        end
    end

    // ── Read Domain ──
    always @(posedge m_axis_aclk or negedge s_axis_aresetn) begin
        if (!s_axis_aresetn) rptr <= 0;
        else if (m_axis_tvalid && m_axis_tready) begin
            rptr <= rptr + 1;
        end
    end

    // ── Synchronization (For Simulation Only) ──
    reg [7:0] wptr_sync1=0, wptr_sync2=0;
    reg [7:0] rptr_sync1=0, rptr_sync2=0;
    
    always @(posedge m_axis_aclk) {wptr_sync2, wptr_sync1} <= {wptr_sync1, wptr};
    always @(posedge s_axis_aclk) {rptr_sync2, rptr_sync1} <= {rptr_sync1, rptr};

    // Ready/Valid logic ensuring we don't overflow/underflow
    assign s_axis_tready = (wptr + 1 != rptr_sync2);
    assign m_axis_tvalid = (wptr_sync2 != rptr);
    assign {m_axis_tlast, m_axis_tdata} = mem[rptr];

endmodule
